import React, { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";

import AdminBookingTable from "../components/AdminBookingTable";
import AdminLayout from "../components/AdminLayout";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const AnimatedCounter = ({ value }) => {
  const [displayValue, setDisplayValue] = useState(0);

  useEffect(() => {
    let frameId;
    const start = performance.now();
    const duration = 650;

    const tick = (time) => {
      const progress = Math.min((time - start) / duration, 1);
      setDisplayValue(Math.round(value * progress));
      if (progress < 1) {
        frameId = requestAnimationFrame(tick);
      }
    };

    frameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameId);
  }, [value]);

  return displayValue;
};

const StatCard = ({ tone, icon, label, value, delay }) => (
  <motion.div
    className={`stat-card ${tone}`}
    initial={{ opacity: 0, y: 18 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.35, delay }}
    whileHover={{ y: -5, scale: 1.01 }}
  >
    <div className="stat-icon">{icon}</div>
    <div>
      <h4>{label}</h4>
      <h2><AnimatedCounter value={value} /></h2>
    </div>
  </motion.div>
);

const AdminDashboard = () => {
  const { fetchInitialData } = useAppContext();
  const [pendingBookings, setPendingBookings] = useState(null);
  const [schedule, setSchedule] = useState([]);
  const [history, setHistory] = useState([]);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const loadData = async () => {
      try {
        const [pendingResponse, scheduleResponse, historyResponse] = await Promise.all([
          api.get("/admin/bookings/pending"),
          api.get("/admin/schedule"),
          api.get("/admin/history"),
          fetchInitialData()
        ]);

        setPendingBookings(pendingResponse.data || []);
        setSchedule(scheduleResponse.data || []);
        setHistory(historyResponse.data || []);
      } catch (error) {
        setMessage(formatErrorMessage(error.response?.data?.detail, "Could not load dashboard data."));
        setPendingBookings([]);
      }
    };

    loadData();
  }, [fetchInitialData]);

  const approvedBookings = useMemo(
    () => history.filter((booking) => booking.status === "approved"),
    [history]
  );
  const rejectedBookings = useMemo(
    () => history.filter((booking) => booking.status === "rejected"),
    [history]
  );
  const stats = useMemo(() => ({
    total: Math.max(schedule.length, (pendingBookings || []).length + history.length),
    pending: (pendingBookings || []).length,
    approved: approvedBookings.length,
    rejected: rejectedBookings.length
  }), [approvedBookings.length, history.length, pendingBookings, rejectedBookings.length, schedule.length]);

  return (
    <AdminLayout title="Admin Control Panel" subtitle="Live booking operations, approvals, and resource schedules.">
      {message ? <motion.div className="alert info" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>{String(message)}</motion.div> : null}

      <motion.section
        className="admin-hero card"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        <div>
          <p className="eyebrow">Operations Dashboard</p>
          <h2>Welcome back, Admin</h2>
          <span>Review incoming requests, approve resources, and track outcomes in real time.</span>
        </div>
      </motion.section>

      {!pendingBookings ? (
        <div className="admin-skeleton-grid">
          <div className="skeleton-line" />
          <div className="skeleton-line" />
          <div className="skeleton-line" />
          <div className="skeleton-line" />
        </div>
      ) : (
        <>
          <section className="admin-stat-grid">
            <StatCard tone="total" icon="T" label="Total Bookings" value={stats.total} delay={0.02} />
            <StatCard tone="pending" icon="P" label="Pending" value={stats.pending} delay={0.08} />
            <StatCard tone="approved" icon="A" label="Approved" value={stats.approved} delay={0.14} />
            <StatCard tone="rejected" icon="R" label="Rejected" value={stats.rejected} delay={0.2} />
          </section>

          <section className="admin-workspace card">
            <div className="admin-workspace-header">
              <div>
                <h3>Pending Requests</h3>
                <p>Latest booking requests awaiting action.</p>
              </div>
            </div>
            <AdminBookingTable bookings={pendingBookings.slice(0, 5)} />
          </section>
        </>
      )}
    </AdminLayout>
  );
};

export default AdminDashboard;
